import React, { useState, useEffect, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import reservationService from '../../services/reservationService';
import tariffService from '../../services/tariffService';
import PageHeader from '../../components/common/PageHeader';
import '../../components/common/shared.css';
import './BookingPage.css';

const TYPE_LABELS = {
  SIMPLE: 'Simple', DOUBLE: 'Double', SUITE: 'Suite', DELUXE: 'Deluxe',
  single: 'Simple', double: 'Double', suite: 'Suite', deluxe: 'Deluxe',
};

const diffDays = (a, b) => {
  if (!a || !b) return 0;
  return Math.max(0, Math.round((new Date(b) - new Date(a)) / 86400000));
};

const BookingPage = () => {
  const { state } = useLocation();
  const navigate  = useNavigate();
  const room      = state?.room;

  const [form, setForm] = useState({
    check_in:  state?.checkIn  || '',
    check_out: state?.checkOut || '',
    guests:    1,
    notes:     '',
  });

  const [loading, setLoading]           = useState(false);
  const [error, setError]               = useState('');
  const [success, setSuccess]           = useState(false);

  // CORRECTION #4 — état du tarif saisonnier applicable
  const [applicableTariff, setApplicableTariff] = useState(null);
  const [tariffLoading, setTariffLoading]       = useState(false);

  // CORRECTION #4 — charger le tarif dès que les dates et le type de chambre sont connus
  const fetchApplicableTariff = useCallback(async (checkIn, checkOut) => {
    if (!room?.type || !checkIn || !checkOut) {
      setApplicableTariff(null);
      return;
    }
    setTariffLoading(true);
    try {
      const tariff = await tariffService.getApplicable(room.type, checkIn, checkOut);
      setApplicableTariff(tariff);
    } finally {
      setTariffLoading(false);
    }
  }, [room?.type]);

  // Charger le tarif initial si les dates sont déjà pré-remplies
  useEffect(() => {
    if (form.check_in && form.check_out) {
      fetchApplicableTariff(form.check_in, form.check_out);
    }
  }, []); // eslint-disable-line

  if (!room) {
    return (
      <div className="booking-no-room">
        <p>Aucune chambre sélectionnée.</p>
        <button className="btn btn--primary" onClick={() => navigate('/client/rooms')}>
          ← Voir les chambres
        </button>
      </div>
    );
  }

  // CORRECTION #4 — calcul du prix effectif
  const basePrice     = Number(room.price_per_night ?? room.price ?? 0);
  const nights        = diffDays(form.check_in, form.check_out);
  // Prix saisonnier si un tarif est applicable, sinon prix de base
  const nightlyPrice  = applicableTariff
    ? applicableTariff.effective_price
    : basePrice;
  const total         = nights * nightlyPrice;
  const hasSeasonal   = applicableTariff && applicableTariff.effective_price !== basePrice;

  const handleChange = ({ target: { name, value } }) => {
    const updated = { ...form, [name]: value };
    setForm(updated);
    // Recharger le tarif dès qu'une date change
    if (name === 'check_in' || name === 'check_out') {
      const ci = name === 'check_in'  ? value : form.check_in;
      const co = name === 'check_out' ? value : form.check_out;
      if (ci && co) fetchApplicableTariff(ci, co);
      else setApplicableTariff(null);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.check_in || !form.check_out) {
      setError('Veuillez sélectionner vos dates.');
      return;
    }
    if (nights < 1) {
      setError("La date de départ doit être après la date d'arrivée.");
      return;
    }
    setLoading(true);
    setError('');
    try {
      await reservationService.create({
        room_id:       room.id,
        check_in:      form.check_in,
        check_out:     form.check_out,
        guests:        form.guests,
        notes:         form.notes,
        // CORRECTION #4 — transmettre le prix saisonnier au backend pour traçabilité
        applied_price: total > 0 ? total : undefined,
      });
      setSuccess(true);
      setTimeout(() => navigate('/client/reservations'), 3000);
    } catch (err) {
      const msg =
        err?.response?.data?.message ||
        err?.response?.data?.error   ||
        err?.message                 ||
        'Erreur lors de la réservation';
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  // CORRECTION #2 — message de succès revu (demande, pas confirmation)
  if (success) {
    return (
      <div className="booking-success">
        <span className="booking-success__icon">✓</span>
        <h3>Demande envoyée !</h3>
        <p>
          Votre demande a bien été envoyée. La réception vous confirmera
          dans les meilleurs délais.
        </p>
        <p className="booking-success__redirect">Redirection vers vos réservations…</p>
      </div>
    );
  }

  const typeLabel = TYPE_LABELS[room.type] ?? room.type;

  return (
    <div>
      {/*
        CORRECTION #1 : suppression de "Chambre {room.number}" dans le sous-titre.
        On affiche uniquement le type et la description.
      */}
      <PageHeader
        title="Réserver une chambre"
        subtitle={`${typeLabel}${room.description ? ` — ${room.description}` : ''}`}
        action={
          <button className="btn btn--outline" onClick={() => navigate(-1)}>
            ← Retour
          </button>
        }
      />

      <div className="booking-layout">
        <form className="booking-form" onSubmit={handleSubmit}>
          {error && <div className="booking-error">{error}</div>}

          <div className="form-grid">
            <div className="form-group">
              <label className="form-label">Date d'arrivée *</label>
              <input
                type="date"
                name="check_in"
                className="form-input"
                value={form.check_in}
                min={new Date().toISOString().split('T')[0]}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label className="form-label">Date de départ *</label>
              <input
                type="date"
                name="check_out"
                className="form-input"
                value={form.check_out}
                min={
                  form.check_in
                    ? new Date(new Date(form.check_in).getTime() + 86400000).toISOString().split('T')[0]
                    : new Date().toISOString().split('T')[0]
                }
                onChange={handleChange}
                required
              />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">Nombre de personnes</label>
            <input
              type="number"
              name="guests"
              className="form-input"
              value={form.guests}
              min={1}
              max={room.capacity ?? 4}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label className="form-label">Remarques</label>
            <textarea
              name="notes"
              className="form-textarea"
              value={form.notes}
              onChange={handleChange}
              placeholder="Demandes particulières, heure d'arrivée estimée…"
            />
          </div>

          <div className="form-actions">
            {/*
              CORRECTION #2 : bouton renommé "Soumettre ma demande" (pas "Confirmer la réservation")
            */}
            <button
              type="submit"
              className="btn btn--gold"
              disabled={loading || nights < 1}
            >
              {loading
                ? <span className="dt-spinner" />
                : `Soumettre ma demande${total ? ` — ${total.toFixed(2)} €` : ''}`
              }
            </button>
          </div>
        </form>

        {/* ── Récapitulatif ── */}
        <aside className="booking-summary">
          <h3 className="booking-summary__title">Récapitulatif</h3>

          {/*
            CORRECTION #1 : pas de numéro de chambre dans le récapitulatif.
            On affiche uniquement type et description.
          */}
          <div className="booking-summary__row">
            <span>Type</span>
            <strong>{typeLabel}</strong>
          </div>
          {room.description && (
            <div className="booking-summary__row">
              <span>Description</span>
              <strong style={{ fontSize: '0.85rem', textAlign: 'right', maxWidth: '60%' }}>
                {room.description}
              </strong>
            </div>
          )}

          {/* CORRECTION #4 — affichage du prix saisonnier */}
          <div className="booking-summary__row">
            <span>Prix de base / nuit</span>
            <strong>{basePrice ? `${basePrice} €` : '—'}</strong>
          </div>

          {tariffLoading && (
            <div className="booking-summary__row">
              <span>Tarif saisonnier</span>
              <span className="dt-spinner" style={{ width: 14, height: 14 }} />
            </div>
          )}

          {!tariffLoading && applicableTariff && (
            <>
              <div className="booking-summary__row">
                <span>Tarif «&nbsp;{applicableTariff.name}&nbsp;»</span>
                <strong style={{ color: 'var(--color-gold)' }}>
                  {applicableTariff.discount_percent > 0
                    ? `-${applicableTariff.discount_percent}%`
                    : 'Actif'}
                </strong>
              </div>
              {hasSeasonal && (
                <div className="booking-summary__row">
                  <span>Prix saisonnier / nuit</span>
                  <strong style={{ color: 'var(--color-gold)' }}>
                    {applicableTariff.effective_price.toFixed(2)} €
                  </strong>
                </div>
              )}
            </>
          )}

          <div className="booking-summary__row">
            <span>Nuits</span>
            <strong>{nights || '—'}</strong>
          </div>

          <div className="booking-summary__divider" />

          <div className="booking-summary__total">
            <span>Total estimé</span>
            <strong>{total ? `${total.toFixed(2)} €` : '—'}</strong>
          </div>

          {applicableTariff && (
            <p style={{ fontSize: '0.75rem', color: 'var(--color-text-muted)', marginTop: 8 }}>
              Tarif saisonnier appliqué. Le montant final sera confirmé par la réception.
            </p>
          )}
        </aside>
      </div>
    </div>
  );
};

export default BookingPage;
